"use client";
import { useLayoutEffect, useRef } from "react";
import Link from "next/link";
import {
  SquarePen,
  PanelsTopLeft,
  UserRound,
  ChartNoAxesColumn,
  History,
  SlidersHorizontal,
} from "lucide-react";
import { usePathname } from "next/navigation";
const links = [
  { name: "Compose", icon: SquarePen },
  { name: "Templates", icon: PanelsTopLeft },
  { name: "Contacts", icon: UserRound },
  { name: "Usage", icon: ChartNoAxesColumn },
  { name: "History", icon: History },
  { name: "Settings", icon: SlidersHorizontal },
];
export function Navigation() {
  const pathname = usePathname();
  const nav = useRef<HTMLElement>(null);
  const highlight = useRef<HTMLSpanElement>(null);
  const initialized = useRef(false);

  useLayoutEffect(() => {
    const container = nav.current;
    const pill = highlight.current;
    if (!container || !pill) return;
    let disposed = false;
    const measure = () => {
      if (disposed) return;
      const active = container.querySelector<HTMLAnchorElement>(
        'a[aria-current="page"]',
      );
      if (!active) {
        pill.style.opacity = "0";
        delete container.dataset.highlightReady;
        return;
      }
      const bounds = active.getBoundingClientRect();
      const parent = container.getBoundingClientRect();
      const x =
        bounds.left - parent.left + container.scrollLeft - container.clientLeft;
      const y =
        bounds.top - parent.top + container.scrollTop - container.clientTop;
      pill.style.width = `${bounds.width}px`;
      pill.style.height = `${bounds.height}px`;
      pill.style.transform = `translate3d(${x}px, ${y}px, 0)`;
      pill.style.opacity = "1";
      container.dataset.highlightReady = "";
      const left = active.offsetLeft - 5;
      const right = active.offsetLeft + active.offsetWidth + 5;
      if (left < container.scrollLeft) container.scrollLeft = left;
      else if (right > container.scrollLeft + container.clientWidth) {
        container.scrollLeft = right - container.clientWidth;
      }
    };
    if (!initialized.current) pill.style.transition = "none";
    measure();
    // Commit the initial position before enabling motion, including in Strict Mode.
    if (!initialized.current) pill.getBoundingClientRect();
    const frame = requestAnimationFrame(() => {
      pill.style.transition = "";
      initialized.current = true;
    });
    const observer = new ResizeObserver(measure);
    observer.observe(container);
    container.querySelectorAll("a").forEach((link) => observer.observe(link));
    void document.fonts.ready.then(measure);
    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [pathname]);

  return (
    <div className="workspace-nav-wrap [container-type:inline-size] w-full">
      <nav
        ref={nav}
        className="workspace-nav relative isolate flex items-center flex-nowrap overflow-x-auto [scrollbar-width:none] gap-[0.15em] w-max max-w-full text-[clamp(14px,_1.75cqw,_17px)] p-[0.32em] [border:1px_solid_var(--nav-line)] rounded-full [background:var(--nav-bg)] shadow-none"
        aria-label="Main navigation"
      >
        <span
          ref={highlight}
          className="workspace-nav-highlight absolute top-0 left-0 rounded-full [background:var(--nav-active-bg)] [outline:1px_solid_var(--nav-active-line)] [outline-offset:-1px] pointer-events-none opacity-[0] [will-change:transform]"
          aria-hidden="true"
        />
        {links.map(({ name, icon: Icon }) => {
          const href = `/${name.toLowerCase()}`;
          return (
            <Link
              key={href}
              href={href}
              className={`relative z-[1] shrink-0 whitespace-nowrap py-[0.62em] px-[0.65em] rounded-full min-h-11 inline-flex items-center gap-[0.5em] text-[0.92em] font-semibold tracking-[-0.01em] ${pathname === href || pathname.startsWith(`${href}/`) ? "text-[var(--nav-active-ink)]" : "text-[var(--nav-muted)] css-hover:text-foreground css-hover:bg-[var(--nav-hover)]"}`}
              aria-label={name}
              aria-current={
                pathname === href || pathname.startsWith(`${href}/`)
                  ? "page"
                  : undefined
              }
            >
              <Icon
                className="workspace-nav-icon w-[1.15em] h-[1.15em] flex-none"
                strokeWidth={1.9}
                aria-hidden="true"
              />
              <span className="workspace-nav-label">
                <span>{name}</span>
              </span>
            </Link>
          );
        })}
      </nav>
    </div>
  );
}
